fn cache(
    p: &Arc<InMemorySecretsProvider>,
    clock: &ManualClock,
    f: impl FnOnce(SecretCacheOptions) -> SecretCacheOptions,
) -> SecretCache<InMemorySecretsProvider> {
    let opts = f(SecretCacheOptions {
        ttl: Duration::from_secs(10),
        clock: Arc::new(clock.clone()),
        ..SecretCacheOptions::default()
    });
    SecretCache::with_options(Arc::clone(p), opts)
}

async fn settle() {
    for _ in 0..20 {
        tokio::task::yield_now().await;
    }
    tokio::time::sleep(Duration::from_millis(20)).await;
}

#[tokio::test]
async fn cache_hits_misses_and_ttl() {
    let p = Arc::new(InMemorySecretsProvider::new().with_secret("a", "1"));
    let clock = ManualClock::new();
    let c = cache(&p, &clock, |o| o);
    assert_eq!(c.get_string("a", None).await.unwrap().as_deref(), Some("1"));
    assert_eq!(c.get_string("a", None).await.unwrap().as_deref(), Some("1"));
    assert!(c.exists("a", None).await.unwrap());
    // negative results are cached too
    assert!(c.get("missing", None).await.unwrap().is_none());
    p.insert("missing", "now");
    assert!(c.get("missing", None).await.unwrap().is_none());
    assert_eq!(
        c.stats(),
        CacheStats {
            hits: 3,
            misses: 2,
            evictions: 0,
            refreshes: 0,
            size: 2
        }
    );
    // expiry
    p.insert("a", "2");
    clock.advance(Duration::from_secs(11));
    assert_eq!(c.get_string("a", None).await.unwrap().as_deref(), Some("2"));
    assert_eq!(c.stats().misses, 3);
    // options are part of the key
    let v1 = GetOptions {
        version: Some("1".into()),
        path: None,
    };
    assert_eq!(
        c.get_string("a", Some(&v1)).await.unwrap().as_deref(),
        Some("1")
    );
    assert_eq!(c.stats().size, 3);
    // errors are not cached
    p.fail_next(Error::unavailable("down"));
    assert_eq!(
        c.get("b", None).await.unwrap_err().code(),
        ErrorCode::Unavailable
    );
    assert!(c.get("b", None).await.unwrap().is_none());
    // invalidate / clear
    c.invalidate("a");
    assert_eq!(c.stats().size, 2);
    c.clear();
    assert_eq!(c.stats().size, 0);
    assert!(Arc::ptr_eq(c.provider(), &p));
    assert!(format!("{c:?}").contains("SecretCache"));
    assert!(format!("{:?}", SecretCacheOptions::default()).contains("ttl"));
}

#[tokio::test]
async fn cache_writes_pass_through_and_invalidate() {
    let p = Arc::new(InMemorySecretsProvider::new().with_secret("dir/a", "1"));
    let clock = ManualClock::new();
    let c = cache(&p, &clock, |o| o);
    assert_eq!(
        c.get_string("dir/a", None).await.unwrap().as_deref(),
        Some("1")
    );
    assert_eq!(c.set("dir/a", "2".into(), None).await.unwrap(), "2");
    assert_eq!(
        c.get_string("dir/a", None).await.unwrap().as_deref(),
        Some("2")
    );
    assert_eq!(c.get_all(Some("dir/")).await.unwrap().len(), 1);
    assert_eq!(c.list(Some("dir/")).await.unwrap().len(), 1);
    assert!(c.metadata("dir/a", None).await.unwrap().is_some());
    c.delete("dir/a", None).await.unwrap();
    assert!(c.get("dir/a", None).await.unwrap().is_none());
    assert_eq!(
        c.delete("dir/a", None).await.unwrap_err().code(),
        ErrorCode::NotFound
    );
    let many = c.get_many(&["dir/a"], None).await.unwrap();
    assert!(many.is_empty());
}

#[tokio::test]
async fn cache_refresh_ahead() {
    let p = Arc::new(InMemorySecretsProvider::new().with_secret("a", "1"));
    let clock = ManualClock::new();
    let c = cache(&p, &clock, |o| o);
    c.get("a", None).await.unwrap();
    p.insert("a", "2");
    clock.advance(Duration::from_secs(9)); // past 80 % of the TTL
    assert_eq!(c.get_string("a", None).await.unwrap().as_deref(), Some("1"));
    // a second hit while refreshing does not start another refresh
    c.get("a", None).await.unwrap();
    settle().await;
    assert_eq!(c.stats().refreshes, 1);
    assert_eq!(c.get_string("a", None).await.unwrap().as_deref(), Some("2"));
    // failed refresh keeps the old value and allows a later refresh
    p.insert("a", "3");
    clock.advance(Duration::from_secs(9));
    p.fail_next(Error::unavailable("down"));
    assert_eq!(c.get_string("a", None).await.unwrap().as_deref(), Some("2"));
    settle().await;
    assert_eq!(c.get_string("a", None).await.unwrap().as_deref(), Some("2"));
    settle().await;
    assert_eq!(c.get_string("a", None).await.unwrap().as_deref(), Some("3"));
    assert_eq!(c.stats().refreshes, 3);
}

#[tokio::test]
async fn cache_stale_while_revalidate() {
    let p = Arc::new(InMemorySecretsProvider::new().with_secret("a", "1"));
    let clock = ManualClock::new();
    let c = cache(&p, &clock, |o| SecretCacheOptions {
        stale_while_revalidate: Duration::from_secs(5),
        refresh_ahead_factor: 1.0,
        ..o
    });
    c.get("a", None).await.unwrap();
    p.insert("a", "2");
    clock.advance(Duration::from_secs(12)); // stale but within the window
    assert_eq!(c.get_string("a", None).await.unwrap().as_deref(), Some("1"));
    settle().await;
    assert_eq!(c.get_string("a", None).await.unwrap().as_deref(), Some("2"));
    clock.advance(Duration::from_secs(20)); // beyond the window → synchronous miss
    p.insert("a", "3");
    assert_eq!(c.get_string("a", None).await.unwrap().as_deref(), Some("3"));
}

#[tokio::test]
async fn cache_lru_eviction() {
    let p = Arc::new(
        InMemorySecretsProvider::new()
            .with_secret("a", "1")
            .with_secret("b", "2")
            .with_secret("c", "3"),
    );
    let clock = ManualClock::new();
    let c = cache(&p, &clock, |o| SecretCacheOptions {
        max_entries: 2,
        ..o
    });
    c.get("a", None).await.unwrap();
    c.get("b", None).await.unwrap();
    c.get("a", None).await.unwrap(); // a is now most recently used
    c.get("c", None).await.unwrap(); // evicts b
    let s = c.stats();
    assert_eq!((s.size, s.evictions), (2, 1));
    let before = p.calls();
    c.get("a", None).await.unwrap();
    assert_eq!(p.calls(), before, "a still cached");
    c.get("b", None).await.unwrap();
    assert_eq!(p.calls(), before + 1, "b was evicted");
    let dynamic: Arc<dyn SecretsProvider> = p.clone();
    let c2 = SecretCache::new(dynamic);
    assert!(c2.get("a", None).await.unwrap().is_some());
}

#[tokio::test]
async fn watch_reports_changes() {
    let p = Arc::new(InMemorySecretsProvider::new().with_secret("w", "1"));
    type Changes = Vec<(Option<String>, Option<String>)>;
    let changes: Arc<Mutex<Changes>> = Arc::default();
    let errors: Arc<Mutex<Vec<String>>> = Arc::default();
    let ch = changes.clone();
    let er = errors.clone();
    let opts = WatchOptions {
        on_error: Some(Arc::new(move |e: &Error| {
            er.lock().unwrap().push(e.code().to_string())
        })),
        get_options: GetOptions::default(),
    };
    assert!(format!("{opts:?}").contains("on_error"));
    let handle = watch(
        p.clone(),
        "w",
        Duration::from_millis(20),
        move |new, old| {
            let s =
                |v: Option<&sdk::secrets::SecretValue>| v.map(|v| v.reveal().unwrap().to_owned());
            ch.lock().unwrap().push((s(new), s(old)));
        },
        opts,
    );
    tokio::time::sleep(Duration::from_millis(50)).await;
    p.insert("w", "2");
    tokio::time::sleep(Duration::from_millis(60)).await;
    p.fail_next(Error::unavailable("blip"));
    tokio::time::sleep(Duration::from_millis(60)).await;
    p.remove("w");
    tokio::time::sleep(Duration::from_millis(60)).await;
    assert!(format!("{handle:?}").contains("stopped: false"));
    handle.stop();
    handle.stop();
    assert!(handle.is_stopped());
    handle.stop_and_wait().await;
    handle.stop_and_wait().await;
    let changes = changes.lock().unwrap().clone();
    assert_eq!(
        changes,
        vec![
            (Some("2".into()), Some("1".into())),
            (None, Some("2".into())),
        ]
    );
    assert_eq!(
        errors.lock().unwrap().clone(),
        vec!["UNAVAILABLE".to_owned()]
    );
}

#[tokio::test]
async fn watch_without_versions_uses_hash_and_survives_panics() {
    let p = Arc::new(InMemorySecretsProvider::unversioned().with_secret("w", "1"));
    let calls = Arc::new(Mutex::new(0));
    let c = calls.clone();
    let handle = watch(
        p.clone(),
        "w".to_owned(),
        Duration::from_millis(10),
        move |_, _| {
            *c.lock().unwrap() += 1;
            panic!("callback failure (expected in tests)");
        },
        WatchOptions {
            on_error: Some(Arc::new(|_| {
                panic!("error callback failure (expected in tests)")
            })),
            ..WatchOptions::default()
        },
    );
    tokio::time::sleep(Duration::from_millis(30)).await;
    p.insert("w", "1"); // same value, new internal version: no change without versions
    tokio::time::sleep(Duration::from_millis(30)).await;
    assert_eq!(*calls.lock().unwrap(), 0);
    p.insert("w", "other");
    p.fail_next(Error::unavailable("x"));
    tokio::time::sleep(Duration::from_millis(60)).await;
    p.insert("w", "third");
    tokio::time::sleep(Duration::from_millis(40)).await;
    assert_eq!(*calls.lock().unwrap(), 2);
    // dropping the last handle stops the watch
    drop(handle);
    tokio::time::sleep(Duration::from_millis(30)).await;
    let before = p.calls();
    tokio::time::sleep(Duration::from_millis(40)).await;
    assert_eq!(p.calls(), before);
}
